import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // consume newline

        char[][] grid = new char[n + 2][m + 2];

        // Initialize padding with '.'
        for (int i = 0; i < n + 2; i++) {
            for (int j = 0; j < m + 2; j++) {
                grid[i][j] = '.';
            }
        }

        // Read grid data
        for (int i = 1; i <= n; i++) {
            String line = scanner.nextLine();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        int output = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == 'W') {
                    for (int k = 0; k < 4; k++) {
                        int nr = i + dr[k];
                        int nc = j + dc[k];
                        if (grid[nr][nc] == 'P') {
                            output++;
                            break; // Each wolf eats at most one pig
                        }
                    }
                }
            }
        }

        System.out.println(output);
        scanner.close();
    }
}

